int32_t GetFsmId(int& fsm_id) {
    std::string parameter, data;

    int32_t ret = Call(ROBOT_API_ID_LOCO_GET_FSM_ID, parameter, data);

    if (ret == 0) {
      go2::JsonizeDataInt json;
      common::FromJsonString(data, json);
      fsm_id = json.data;
    }

    return ret;
  }

