int32_t Move(float vx, float vy, float vyaw) {
        MoveParameter param;

        param.vx = vx;
        param.vy = vy;
        param.vyaw = vyaw;

        std::string parameter = common::ToJsonString(param);
        std::string data;

        return Call(ROBOT_API_ID_AGV_MOVE, parameter, data);
    }

int32_t HeightAdjust(float vz) {
        std::string parameter, data;

        go2::JsonizeDataFloat json;
        json.data = vz;

        parameter = common::ToJsonString(json);

        return Call(ROBOT_API_ID_AGV_HEIGHT_ADJUST, parameter, data);
    }

def GetFsmId(self):
        p = {}
        parameter = json.dumps(p)
        code, data = self._Call(ROBOT_API_ID_LOCO_GET_FSM_ID, parameter)
        if code != 0:
            return code, None
        js = json.loads(data)
        return code, js.get("data")

def SetFsmId(self, fsm_id: int):
        p = {}
        p["data"] = fsm_id
        parameter = json.dumps(p)
        code, data = self._Call(ROBOT_API_ID_LOCO_SET_FSM_ID, parameter)
        return code

def SetBalanceMode(self, balance_mode: int):
        p = {}
        p["data"] = balance_mode
        parameter = json.dumps(p)
        code, data = self._Call(ROBOT_API_ID_LOCO_SET_BALANCE_MODE, parameter)
        return code

def SetStandHeight(self, stand_height: float):
        p = {}
        p["data"] = stand_height
        parameter = json.dumps(p)
        code, data = self._Call(ROBOT_API_ID_LOCO_SET_STAND_HEIGHT, parameter)
        return code

def SetTaskId(self, task_id: float):
        p = {}
        p["data"] = task_id
        parameter = json.dumps(p)
        code, data = self._Call(ROBOT_API_ID_LOCO_SET_ARM_TASK, parameter)
        return code

def SetSpeedMode(self, speed_mode: int):
        p = {}
        p["data"] = speed_mode
        parameter = json.dumps(p)
        code, data = self._Call(ROBOT_API_ID_LOCO_SET_SPEED_MODE, parameter)
        return code

def SwitchToUserCtrl(self):
        p = {}
        p["data"] = False
        parameter = json.dumps(p)
        code, data = self._Call(ROBOT_API_ID_LOCO_SWITCH_TO_USER_CTRL, parameter)
        return code

def SwitchToInternalCtrl(self, mode: InternalFsmMode):
        p = {}
        if mode == InternalFsmMode.LAST:
            p["data"] = 0
        elif mode == InternalFsmMode.PASSIVE:
            p["data"] = 1
        elif mode == InternalFsmMode.WALKRUN:
            p["data"] = 2
        else:
            raise ValueError(f"Invalid InternalFsmMode: {mode}")
        parameter = json.dumps(p)
        code, data = self._Call(ROBOT_API_ID_LOCO_SWITCH_TO_INTERNAL_CTRL, parameter)
        return code

def HighStand(self):
        UINT32_MAX = (1 << 32) - 1
        self.SetStandHeight(UINT32_MAX)

def LowStand(self):
        UINT32_MIN = 0
        self.SetStandHeight(UINT32_MIN)

def Move(self, vx: float, vy: float, vyaw: float, continous_move: bool = False):
        duration = 864000.0 if continous_move else 1
        self.SetVelocity(vx, vy, vyaw, duration)

def ShakeHand(self, stage: int = -1):
        if stage == 0:
            self.first_shake_hand_stage_ = False
            self.SetTaskId(2)
        elif stage == 1:
            self.first_shake_hand_stage_ = True
            self.SetTaskId(3)
        else:
            self.first_shake_hand_stage_ = not self.first_shake_hand_stage_
            return self.SetTaskId(3 if self.first_shake_hand_stage_ else 2)

def ExecuteAction(self, action_id: int):
        p = {}
        p["data"] = action_id
        parameter = json.dumps(p)
        code, data = self._Call(ROBOT_API_ID_ARM_ACTION_EXECUTE_ACTION, parameter)
        return code

def GetActionList(self):
        p = {}
        parameter = json.dumps(p)
        code, data = self._Call(ROBOT_API_ID_ARM_ACTION_GET_ACTION_LIST, parameter)
        if code == 0:
            return code, json.loads(data)
        else:
            return code, None

def GetVolume(self):
        p = {}
        parameter = json.dumps(p)
        code, data = self._Call(ROBOT_API_ID_AUDIO_GET_VOLUME, parameter)
        if code == 0:
            return code, json.loads(data)
        else:
            return code, None

def SetVolume(self, volume: int):
        p = {}
        p["volume"] = volume
        parameter = json.dumps(p)
        code, data = self._Call(ROBOT_API_ID_AUDIO_SET_VOLUME, parameter)
        return code

def PlayStream(self, app_name: str, stream_id: str, pcm_data: bytes):
        param = json.dumps({"app_name": app_name, "stream_id": stream_id})
        pcm_list = list(pcm_data) 
        return self._CallRequestWithParamAndBin(ROBOT_API_ID_AUDIO_START_PLAY, param, pcm_list)
